/** Resolve only exact canonical names or documented semantic aliases; never fetch URLs. */
export function getIcon(name: string): IconDefinition {
  if (typeof name !== "string") throw new TypeError("Unknown icon name");
  if (Object.hasOwn(icons,name)) return icons[name as IconName];
  if (Object.hasOwn(iconAliases,name)) return icons[iconAliases[name as IconAlias]];
  throw new TypeError("Unknown icon name: " + name.slice(0,100));
}
export function isIconName(name: string): name is IconName { return typeof name === "string" && Object.hasOwn(icons,name); }
